import React,{useState} from 'react';
import {usePersistentState,downloadText} from './shared';
import {calendarEvent} from '../collectionModel.mjs';
import {personalExport,clearPersonal,storageFailed} from '../storageModel.mjs';
export function PrivacyPanel(){const [preview,setPreview]=useState(null),[confirm,setConfirm]=useState(false),[message,setMessage]=useState('');return <section className="privacy-panel"><p className="modal-lead">Your saved workspace is local to this browser.</p><p>Profiles, conversations, scenarios, notes, saved courses and preferences are device-local. Other people using this browser may be able to read them. This app has no cloud account or automatic backup. When you request advice or evaluation, the server receives the question and supplied declarations to process that request. Clearing browser records does not erase server sessions or logs.</p><button className="secondary-button" onClick={()=>setPreview(personalExport())}>Review stored personal records</button>{preview && <details open className="workspace-export"><summary>Personal export preview</summary><p>This file includes private declarations and conversations. Review it before sharing.</p><pre role="region" tabIndex={0} aria-label="Export preview">{JSON.stringify(preview,null,2)}</pre><button className="secondary-button" onClick={()=>downloadText('curricupath-personal-records.json',JSON.stringify(preview,null,2),'application/json')}>Export personal records</button></details>}<h3>Clear this browser’s personal workspace</h3><p>Clears profile, conversations, drafts, notes, collections, history and feedback. Theme, motion and sidebar appearance remain. Download a backup first if you need these records. This does not revoke files you already shared or erase server logs.</p>{confirm?<div className="workspace-warning"><p>Confirm clearing personal data from this browser? This cannot be undone here.</p><button className="secondary-button" onClick={()=>{if(clearPersonal()){location.hash='#home';location.reload();}else{setConfirm(false);setMessage('The browser denied deletion. Session memory was cleared, but persistent data may remain. Clear site data in browser settings before using a shared device.');}}}>Confirm clear personal workspace</button><button className="text-button" onClick={()=>setConfirm(false)}>Keep personal records</button></div>:<button className="secondary-button" onClick={()=>setConfirm(true)}>Clear personal workspace</button>}<p role="status">{message || (storageFailed()?'Persistence is unavailable or has failed. New changes may last for this visit only.':'Local storage is available for this visit.')}</p></section>;}
export function PersonalIntention(){const [goal,setGoal,status]=usePersistentState('curricupath-study-intention-v1','');const [undo,setUndo]=useState(''),[date,setDate]=useState(''),[time,setTime]=useState(''),[message,setMessage]=useState('');return <details className="personal-intention"><summary>A study intention of your own</summary><p>Optional, local and editable. Choose something useful; there is no streak or score to keep up with.</p><label className="workspace-field">Your study intention<input name="study-intention" autoComplete="off" maxLength={120} value={goal} onChange={e=>setGoal(e.target.value)} placeholder="For example, understand one prerequisite…"/></label>{goal && <button className="text-button" onClick={()=>{setUndo(goal);setGoal('');}}>Clear study intention</button>}{undo && <button className="text-button" onClick={()=>{setGoal(undo);setUndo('');}}>Undo intention clear</button>}<p role="status">{status==='error'?'Saving failed; this intention may last only for this visit.':'Remembered on this device.'}</p>{goal && <details><summary>Choose a personal study time</summary><p>Create a calendar file for a time you choose. No reminder is sent. This is not an official module date, offering or timetable slot. Time zone: Africa/Johannesburg (UTC+02:00).</p><div className="calendar-fields"><label className="workspace-field">Study date<input type="date" name="study-date" value={date} onChange={e=>setDate(e.target.value)}/></label><label className="workspace-field">Start time<input type="time" name="study-time" value={time} onChange={e=>setTime(e.target.value)}/></label></div><p>Duration: 1 hour · title: {goal}</p><button className="secondary-button" onClick={()=>{try{downloadText('curricupath-personal-study.ics',calendarEvent({title:goal,date,time}),'text/calendar');setMessage('Calendar file prepared for your chosen time. Import it into your own calendar.');}catch(e){setMessage(e.message);}}}>Export personal calendar time</button><p role="status">{message}</p></details>}</details>;}
export function ContinuationCard({record,profileKey,onResume,onDismiss}){if(!record || !record.hash)return null;const historical=record.academic && record.contextKey!==profileKey;return <section className="task-continuation"><span className="eyebrow">A thread to pick up</span><h2>{record.label}</h2><p>{historical?'Your academic context changed. Resume the inspection, then evaluate again before acting.':'Your last meaningful workspace on this browser. Resume the task at your own pace.'}</p><div className="workspace-toolbar"><button className="secondary-button" onClick={()=>onResume(record.hash)}>Resume this task</button><button className="text-button" onClick={onDismiss}>Dismiss continuation</button></div></section>;}
