import React,{useEffect,useRef,useState} from 'react';
import {getJson} from './shared';
export function ConceptSearch({enabled,onOpenCourse}){
 const [query,setQuery]=useState(''),[results,setResults]=useState(null),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const generation=useRef(0),controller=useRef(null);
 const cancel=()=>{generation.current++;controller.current?.abort();setBusy(false);};
 useEffect(()=>()=>{generation.current++;controller.current?.abort();},[]);
 useEffect(()=>{if(!enabled){cancel();setResults(null);}},[enabled]);
 if(!enabled)return null;
 const search=async e=>{e.preventDefault();if(!query.trim() || busy)return;const token=++generation.current;controller.current=new AbortController();setBusy(true);setError('');setResults(null);
  try{const data=await getJson('/search/semantic',{method:'POST',headers:{'Content-Type':'application/json'},signal:controller.current.signal,body:JSON.stringify({query:query.trim(),item_type:'public_course',limit:12})});if(token===generation.current)setResults([...new Map(data.results.filter(r=>r.item_type==='public_course').map(r=>[r.item_id,r])).values()]);}
  catch(e){if(token===generation.current && e.name!=='AbortError')setError(`Concept search could not finish. ${e.message}`);}
  finally{if(token===generation.current)setBusy(false);}
 };
 return <details className="concept-search"><summary>Find a course by meaning</summary><p>Describe what you want to learn, even if you do not know the course title. These are relevance matches, not academic eligibility or university credit decisions. Only this search phrase is sent; your profile is not included.</p><form onSubmit={search}><label className="workspace-field">What would you like to understand?<input name="concept-search" autoComplete="off" maxLength={1000} required value={query} onChange={e=>{cancel();setQuery(e.target.value);setResults(null);setError('');}} placeholder="For example, how computers learn patterns…"/></label><div className="workspace-toolbar"><button className="secondary-button" disabled={busy} aria-busy={busy}>{busy?'Finding related learning…':'Search by meaning'}</button>{busy && <button type="button" className="text-button" onClick={cancel}>Cancel concept search</button>}</div></form>{error && <p className="workspace-warning" role="alert">{error} Your phrase is kept; try again or use the regular catalogue filters.</p>}<p role="status">{results?`${results.length} related public courses found.`:''}</p>{results?.map(r=><article key={r.item_id}><strong>{r.title || r.item_id}</strong><p>{r.text || r.content || 'Open the recorded course to inspect its details and evidence.'}</p><button className="text-button" onClick={()=>onOpenCourse(r.item_id)}>View related course</button></article>)}{results?.length===0 && <p>No matches were supplied. Try another description; the regular catalogue remains available.</p>}</details>;
}
