import {ConceptSearch} from "./ConceptSearch";
import {LearningCollections} from "./LearningCollections";
import {safeLocal} from "../storageModel.mjs";
import React, { useState } from "react";
import { ArrowUpRight, Search, X, Compass, Bookmark, Columns3 } from "lucide-react";

const programmeName = (code) =>
  ({ EFA03: "Electrical Engineering", EFA04: "Information Engineering" })[
    code
  ] || "Your degree, your direction";
import { Drawer } from "./Shell";
import { TopicArtwork } from "./TopicArtwork";
import { ChapterKicker } from "./AtlasArtwork";
import {
  TOPICS,
  courseMatchesTopic,
  DEFAULT_DISCOVERY,
  discoveryCourses,
} from "../exploreModel.mjs";
import { AsyncPanel, titleCase } from "./shared";
export function ExplorePage({
  conceptSearchEnabled,
  collections,onCollections,collectionPersistence,
  tab,
  setTab,
  courses,
  careers,
  loading,
  error,
  onRetry,
  onOpenCourse,
  options,
  onOptions,
  savedCourses = [],
  onSaveCourse,
  comparisonIds = [],
  onCompare,
  onOpenComparison,
  onClearComparison,
}) {
  const { q: query, topic } = options;
  const setQuery = (value) => onOptions({ q: value }, true);
  const setTopic = (value) => onOptions({ topic: value });
  const [interestNotice,setInterestNotice]=useState('');
  const [selectedCareer, setSelectedCareer] = useState(null);
  const list = discoveryCourses(
    options.saved
      ? courses.filter((c) => savedCourses.includes(c.course_id))
      : courses,
    options,
  );
  const activeFilters = [
    ["saved", options.saved && "Saved courses"],
    ["topic", TOPICS.find((item) => item.id === topic)?.title],
    ["provider", options.provider],
    ["level", options.level && titleCase(options.level)],
    ["workload", options.workload && `${titleCase(options.workload)} workload`],
  ].filter(([, label]) => label);
  const paths = careers.filter((c) =>
    [c.display_name, ...(c.related_interests || [])]
      .join(" ")
      .replaceAll("_", " ")
      .toLowerCase()
      .includes(query.toLowerCase()),
  );
  return (
    <div className="explore-page page-content atlas-explore">
      <div className="view-heading">
        <div>
          <ChapterKicker index="03">FOLLOW YOUR CURIOSITY</ChapterKicker>
          <h1>There’s more than one way forward.</h1>
          <p>Public courses and career directions worth exploring.</p>
        </div>
      </div>
      {tab === "courses" && <LearningCollections state={collections} onChange={onCollections} courses={courses} savedIds={savedCourses} onOpen={onOpenCourse} onUnsave={onSaveCourse} persistence={collectionPersistence}/>}
      {tab === "courses" && <ConceptSearch enabled={conceptSearchEnabled} onOpenCourse={onOpenCourse}/>}
      {tab === "courses" && (
        <section className="topic-discovery" aria-labelledby="topic-heading">
          <div className="topic-section-heading">
            <div>
              <span className="eyebrow">A spark of curiosity</span>
              <h2 id="topic-heading">Where will you go next?</h2>
            </div>
            <button
              className="text-button topic-reset"
              onClick={() => setTopic(null)}
              aria-pressed={!topic}
            >
              All topics <ArrowUpRight size={15} />
            </button>
          </div>
          <div className="topic-grid">
            {TOPICS.map((item, index) => {
              const count = courses.filter((course) =>
                courseMatchesTopic(course, item.id),
              ).length;
              return (
                <button
                  key={item.id}
                  className={`topic-card topic-${item.id}`}
                  aria-pressed={topic === item.id}
                  onClick={() => setTopic(topic === item.id ? null : item.id)}
                >
                  <div className="topic-card-top">
                    <span className="topic-number">0{index + 1}</span>
                    <ArrowUpRight size={19} />
                  </div>
                  <TopicArtwork topic={item.id} />
                  <span className="topic-card-copy">
                    <strong>{item.title}</strong>
                    <span>{item.description}</span>
                    <small>
                      {loading
                        ? "Loading courses…"
                        : `${count} public course${count === 1 ? "" : "s"}`}
                    </small>
                  </span>
                </button>
              );
            })}
          </div>
        </section>
      )}
      <div className="explore-controls">
        <label className="explore-search">
          <Search size={22} />
          <input
            aria-label="Search courses and careers"
            placeholder="An interest, a skill, a direction…"
            value={query}
            name="discovery-search"
            autoComplete="off"
            maxLength={200}
            onChange={(e) => setQuery(e.target.value)}
          />
          {query && (
            <button
              className="icon-button"
              aria-label="Clear search"
              onClick={() => setQuery("")}
            >
              <X size={17} />
            </button>
          )}
        </label>
        <div role="group" className="segmented" aria-label="Explore category">
          {["courses", "careers"].map((t) => (
            <button
              key={t}
              className={tab === t ? "active" : ""}
              aria-pressed={tab === t}
              onClick={() => {
                setTab(t);
                setSelectedCareer(null);
              }}
            >
              {t === "courses" ? "Courses" : "Careers"}
            </button>
          ))}
        </div>
      </div>
      <div className="explore-caption" role="status" aria-live="polite">
        <span>
          {loading
            ? "Finding possibilities…"
            : `${tab === "courses" ? list.length : paths.length} ${(tab === "courses" ? list.length : paths.length) === 1 ? (tab === "courses" ? "course" : "career") : tab} to explore${tab === "courses" && topic ? ` · ${TOPICS.find((item) => item.id === topic)?.title}` : ""}`}
        </span>
        <span>Public courses · Separate from your Wits curriculum</span>
      </div>
      {tab === "courses" && (
        <section
          className="discovery-filter-panel"
          aria-label="Narrow the course catalogue"
        >
          <div className="discovery-filter-heading">
            <span className="eyebrow">Make room for what interests you</span>
            <button
              className="text-button"
              disabled={
                !query && !activeFilters.length && options.sort === "catalogue"
              }
              onClick={() => onOptions({ ...DEFAULT_DISCOVERY })}
            >
              Reset filters
            </button>
          </div>
          <label className="saved-course-filter">
            <input
              type="checkbox"
              checked={options.saved}
              onChange={(e) => onOptions({ saved: e.target.checked })}
            />
            Only saved courses{" "}
            <small>{savedCourses.length} saved on this device</small>
          </label>
          <div className="discovery-filter-grid">
            {[
              ["provider", "Provider"],
              ["level", "Level"],
              ["workload", "Workload"],
            ].map(([key, label]) => (
              <label key={key}>
                {label}
                <select
                  aria-label={`Course ${key}`}
                  value={options[key]}
                  onChange={(event) => onOptions({ [key]: event.target.value })}
                >
                  <option value="">
                    All{" "}
                    {key === "provider"
                      ? "providers"
                      : key === "level"
                        ? "levels"
                        : "workloads"}
                  </option>
                  {[
                    ...new Set(
                      courses.map((course) => course[key]).filter(Boolean),
                    ),
                  ]
                    .sort()
                    .map((value) => (
                      <option key={value} value={value}>
                        {titleCase(value)}
                      </option>
                    ))}
                </select>
              </label>
            ))}
            <label>
              Sort by
              <select
                aria-label="Sort public courses"
                value={options.sort}
                onChange={(event) => onOptions({ sort: event.target.value })}
              >
                <option value="catalogue">Catalogue order</option>
                <option value="title">Title A–Z</option>
                <option value="rating">Learner rating ↓</option>
              </select>
            </label>
          </div>
          {activeFilters.length > 0 && (
            <div role="group"
              className="active-discovery-filters"
              aria-label="Active course filters"
            >
              {activeFilters.map(([key, label]) => (
                <button
                  key={key}
                  aria-label={`Remove ${label} filter`}
                  onClick={() => onOptions({ [key]: DEFAULT_DISCOVERY[key] })}
                >
                  {label}
                  <X size={13} aria-hidden="true" />
                </button>
              ))}
            </div>
          )}
          {options.sort === "rating" && (
            <p className="discovery-rating-note">
              Highest recorded ratings first. Courses without ratings appear
              last. Ratings reflect learner feedback.
            </p>
          )}
        </section>
      )}
      {loading && (
        <div className="course-skeletons" aria-hidden="true">
          {[0, 1, 2].map((i) => (
            <div className="course-skeleton" key={i}>
              <span />
              <span />
              <span />
            </div>
          ))}
        </div>
      )}
      {tab==='courses' && topic && <div className="workspace-toolbar"><button className="text-button" onClick={()=>{setInterestNotice(safeLocal.setItem('curricupath-studio-focus',topic)?'Interest kept on this device.':'Interest chosen for this visit; local saving failed.');}}>Keep this interest on this device</button><button className="text-button" onClick={()=>onOptions({...DEFAULT_DISCOVERY})}>Explore another direction</button><span role="status">{interestNotice || 'Discovery preference only; your academic declarations are unchanged.'}</span></div>}
      {tab==='careers' && <p className="workspace-warning">These are illustrative career directions linked to recorded learning. They do not promise employment, professional certification or degree credit.</p>}
      {tab === "courses" && <p className="discovery-match-note">{options.topic ? `Matching recorded tags for ${TOPICS.find(t=>t.id===options.topic)?.title || options.topic}.` : 'Results use the recorded catalogue attributes and your selected filters.'} These are public learning options, not a degree eligibility assessment.</p>}
      {tab === "courses" && <section className="comparison-tray" aria-label="Your course comparison"><div><Columns3 size={19} aria-hidden="true" /><span><strong>{comparisonIds.length ? `${comparisonIds.length} of 3 courses selected` : "See your options side by side"}</strong><small>Use Compare beneath any course. Choose up to three.</small></span></div><div><button className="secondary-button" disabled={comparisonIds.length < 2} onClick={onOpenComparison}>Compare courses</button>{comparisonIds.length > 0 && <button className="text-button" onClick={onClearComparison}>Clear</button>}</div><span className="visually-hidden" role="status">{comparisonIds.length} courses selected for comparison</span></section>}
      {error ? (
        <AsyncPanel
          title={`Your ${tab} could not be loaded`}
          error={error}
          onRetry={onRetry}
        />
      ) : tab === "courses" ? (
        <div className="explore-list">
          {list.map((c, i) => (
            <CourseRow
              key={c.course_id}
              course={c}
              index={i}
              matchingTags={TOPICS.find(t=>t.id===topic)?.tags.filter(tag=>[...(c.topic_tags || []),...(c.interest_tags || [])].includes(tag)) || []}
              onOpen={onOpenCourse}
              saved={savedCourses.includes(c.course_id)}
              onSave={onSaveCourse}
              compared={comparisonIds.includes(c.course_id)}
              compareFull={comparisonIds.length >= 3}
              onCompare={onCompare}
            />
          ))}
        </div>
      ) : (
        <div className="career-list">
          {paths.map((c) => (
            <button
              className="career-list-row"
              key={c.career_tag}
              onClick={() => setSelectedCareer(c)}
            >
              <span className="shortcut-icon">
                <Compass size={21} />
              </span>
              <span>
                <strong>{c.display_name}</strong>
                <small>
                  {(c.related_interests || [])
                    .map((v) => v.replaceAll("_", " "))
                    .join(" · ")}
                </small>
              </span>
              <span>{c.course_count} courses</span>
              <ArrowUpRight size={19} />
            </button>
          ))}
        </div>
      )}
      {!loading && !error && !(tab === "courses" ? list : paths).length && (
        <div className="empty-panel">
          <p>
            {options.saved
              ? "No saved courses match. Save a course from the catalogue or clear your filters."
              : "No catalogue records match all of these filters. Clear a filter or choose another direction."}
          </p>
          <button
            className="secondary-button"
            onClick={() => onOptions({ ...DEFAULT_DISCOVERY })}
          >
            Clear discovery filters
          </button>
        </div>
      )}
      {selectedCareer && (
        <Drawer
          title={selectedCareer.display_name}
          onClose={() => setSelectedCareer(null)}
        >
          <p className="modal-lead">
            Public courses connected to this career direction.
          </p>
          {selectedCareer.courses.map((c, i) => (
            <CourseRow
              key={c.course_id}
              course={c}
              index={i}
              onOpen={(id) => {
                setSelectedCareer(null);
                onOpenCourse(id);
              }}
            />
          ))}
        </Drawer>
      )}
    </div>
  );
}
function CourseRow({ course: c, matchingTags=[], index, onOpen, saved, onSave, compared, compareFull, onCompare }) {
  return (
    <div className="course-entry">
      <button className="course-list-row" onClick={() => onOpen(c.course_id)}>
        <span className="course-number">
          {String(index + 1).padStart(2, "0")}
        </span>
        <span className="course-row-body">
          <span className="eyebrow">
            {c.provider} <span>· {c.level}</span>
          </span>
          <strong>{c.title}</strong>
          <small>{c.description}</small>
          {matchingTags.length>0 && <small>Recorded matching tags: {matchingTags.map(t=>t.replaceAll("_"," ")).join(", ")}</small>}
          <span className="course-row-meta">
            {c.category?.replaceAll("_", " ")} <span>·</span> {c.workload}{" "}
            workload
          </span>
        </span>
        <span className="course-rating">
          {c.rating_mean ? (
            <>
              <span>
                ★ {c.rating_mean}/{c.rating_scale || 5}
              </span>
              <small>
                {Number(c.rating_count || 0).toLocaleString()} ratings
              </small>
            </>
          ) : (
            "View course"
          )}
        </span>
        <ArrowUpRight size={20} />
      </button>
      {onSave && (
        <button
          className="course-save icon-button"
          aria-label={`${saved ? "Unsave" : "Save"} ${c.title}`}
          aria-pressed={Boolean(saved)}
          onClick={() => onSave(c.course_id)}
        >
          <Bookmark size={19} fill={saved ? "currentColor" : "none"} aria-hidden="true" /><span>{saved?"Saved":"Save course"}</span>
        </button>
      )}
      {onCompare && <button className="course-compare" aria-label={`${compared ? "Remove" : "Compare"} ${c.title}${compared ? " from comparison" : ""}`} aria-pressed={Boolean(compared)} disabled={!compared && compareFull} onClick={() => onCompare(c.course_id)}><Columns3 size={15} aria-hidden="true" />{compared ? "In comparison · Remove" : "Compare"}</button>}
    </div>
  );
}
