import React,{useState} from 'react';
import {COMPARISON_FIELDS} from '../discoveryTools.mjs';
import {comparisonState,ratingComparable} from '../collectionModel.mjs';
import {useMediaQuery} from '../interaction';
export function CourseComparison({courses,savedIds,onSave,onRemove,onOpen,onClear}){
 const narrow=useMediaQuery('(max-width:600px)');const [mode,setMode]=useState('auto'),[differences,setDifferences]=useState(false);
 const cards=mode==='cards' || (mode==='auto' && narrow);
 const rows=COMPARISON_FIELDS.map(([label,value])=>({label,value,...comparisonState(courses,label==='Learner rating'?ratingComparable:value)})).filter(row=>!differences || row.different || row.missing);
 const actions=course=><div className="workspace-toolbar"><button className="text-button" onClick={()=>onOpen(course.course_id)}>View details</button><button className="text-button" aria-pressed={savedIds.includes(course.course_id)} onClick={()=>onSave(course.course_id)}>{savedIds.includes(course.course_id)?'Saved · Unsave':'Save course'}</button><button className="text-button" aria-label={`Remove ${course.title} from comparison`} onClick={()=>onRemove(course.course_id)}>Remove</button></div>;
 return <div className="course-comparison"><div className="comparison-intro"><span className="eyebrow">Your decision workbench</span><h3>Find the difference that matters.</h3><p>Compare recorded attributes of up to three public courses. These options do not confirm Wits eligibility.</p></div><div className="comparison-controls"><label><input type="checkbox" checked={differences} onChange={e=>setDifferences(e.target.checked)}/> Show differences and evidence gaps</label><button className="text-button" onClick={onClear}>Clear comparison</button></div><label className="workspace-field">Comparison reading mode<select value={mode} onChange={e=>setMode(e.target.value)}><option value="auto">Adapt to screen</option><option value="table">Side by side table</option><option value="cards">Course reading cards</option></select></label><p className="helper-text">A difference requires comparable recorded values from every course. Missing values are labelled evidence gaps. Ratings are compared as proportions of their supplied scales; counts remain visible.</p>{courses.length<2 && <p role="status">Choose at least two courses from Explore.</p>}{cards?<div className="comparison-reading-cards">{courses.map(course=><article key={course.course_id}><span className="eyebrow">{course.provider}</span><h3>{course.title}</h3><dl>{rows.map(row=><div key={row.label}><dt>{row.label}{row.missing>0?' · evidence gap':row.different?' · recorded difference':''}</dt><dd>{row.value(course)}</dd></div>)}</dl>{actions(course)}</article>)}</div>:courses.length>0 && <div className="comparison-scroll" role="region" tabIndex={0} aria-label="Course comparison table; scroll horizontally on narrow screens"><table><caption className="visually-hidden">Recorded public course comparison</caption><thead><tr><th scope="col">Recorded attribute</th>{courses.map(course=><th key={course.course_id} scope="col"><strong>{course.title}</strong><small>{course.provider}</small></th>)}</tr></thead><tbody>{rows.map(row=><tr key={row.label}><th scope="row">{row.label}{row.missing>0 && <small>Evidence gap</small>}</th>{courses.map(course=><td key={course.course_id}>{row.value(course)}</td>)}</tr>)}<tr><th scope="row">Next step</th>{courses.map(course=><td key={course.course_id}>{actions(course)}</td>)}</tr></tbody></table></div>}{differences && !rows.length && courses.length>=2 && <p role="status">No comparable recorded differences or evidence gaps in these attributes. Read the full descriptions and sources.</p>}</div>;
}
