import { safeLocal } from "../storageModel.mjs";
import React, { useState } from "react";
import { ArrowUpRight, Bookmark, Check, RotateCcw } from "lucide-react";
import { TOPICS, DEFAULT_DISCOVERY, discoveryCourses } from "../exploreModel.mjs";
import { TopicArtwork } from "./TopicArtwork";
import { AsyncPanel,usePersistentState } from "./shared";
import { discoveryPick } from "../discoveryTools.mjs";
import { Shuffle } from "lucide-react";

const FOCUS_KEY = "curricupath-studio-focus";
function storedFocus() {
  try {
    const id = safeLocal.getItem(FOCUS_KEY);
    return TOPICS.some((topic) => topic.id === id) ? id : null;
  } catch { return null; }
}
const stories = {
  learning: ["Find the pattern.", "Shape what comes next.", "Explore the tools behind prediction, intelligence and new ideas."],
  networks: ["Make a connection.", "Open a possibility.", "Discover how information moves between people, devices and the world."],
  embedded: ["Imagine a thing.", "Bring it to life.", "Follow the meeting point of circuits, software and physical systems."],
};

export function InterestStudio({ courses, loading, error, onRetry, savedCourses, onSaveCourse, onOpenCourse, onNavigate }) {
  const [focus, setFocus] = useState(storedFocus);
  const [storageMessage, setStorageMessage] = useState("");
  const [lastPick, setLastPick] = useState(null);
  const topic = TOPICS.find((item) => item.id === focus);
  const active = topic || TOPICS[0];
  const story = stories[active.id];
  const matches = discoveryCourses(courses, { ...DEFAULT_DISCOVERY, topic: active.id, sort: "rating" });
  const saved = new Set(savedCourses.map((course) => course.course_id));
  function choose(id) {
    setFocus(id);
    try {
      const persisted = id ? safeLocal.setItem(FOCUS_KEY, id) : safeLocal.removeItem(FOCUS_KEY);
      setStorageMessage(persisted ? (id ? "Interest remembered on this device." : "Interest reset. All directions remain open.") : "Interest selected for this visit; device storage is unavailable.");
    } catch { setStorageMessage("Interest selected for this visit; device storage is unavailable."); }
  }
  return (
    <section className={`interest-studio studio-${active.id}`} aria-labelledby="studio-heading">
      <div className="studio-heading">
        <div><span className="eyebrow">The possibility studio</span><h2 id="studio-heading" tabIndex={-1}>What pulls you forward?</h2></div>
        <p>Choose an interest. Find one small place to begin.</p>
      </div>
      <div className="studio-choices" role="group" aria-label="Choose your discovery interest">
        {TOPICS.map((item) => <button key={item.id} aria-pressed={focus === item.id} onClick={() => choose(item.id)}>{item.title}{focus === item.id && <Check size={15} aria-hidden="true" />}</button>)}
        {focus && <button className="studio-reset" onClick={() => choose(null)}><RotateCcw size={14} aria-hidden="true" /> Reset interest</button>}
      </div>
      <p className="studio-storage" role="status">{storageMessage || (focus ? "Your chosen interest · remembered on this device" : "An invitation to explore · choose any direction")}</p>
      <div className="studio-composition">
        <div className="studio-poster">
          <span className="studio-folio" aria-hidden="true">0{TOPICS.indexOf(active) + 1} / FIELD NOTES</span>
          <TopicArtwork topic={active.id} />
          <h3>{story[0]}<em>{story[1]}</em></h3>
          <p>{story[2]}</p>
          <button className="studio-browse" onClick={() => onNavigate("explore", { tab: "courses", ...DEFAULT_DISCOVERY, topic: active.id, sort: "rating" })}>Explore {active.title.toLowerCase()} <ArrowUpRight size={18} aria-hidden="true" /></button>
          <div className="studio-detour"><button disabled={loading || Boolean(error) || !matches.length} onClick={() => { const course = discoveryPick(matches, lastPick); if (course) { setLastPick(course.course_id); onOpenCourse(course.course_id); } }}><Shuffle size={17} aria-hidden="true" /> Surprise me with a course</button><small>A random pick from {active.title.toLowerCase()}. No immediate repeat when alternatives exist.</small></div>
        </div>
        <div className="studio-course-panel">
          <div className="studio-course-heading"><span className="eyebrow">A place to begin</span><span>{loading || error ? "—" : matches.length} courses</span></div>
          <p className="studio-course-note">Public courses with recorded learner ratings. These are discovery options, separate from your degree.</p>
          {(loading || error) ? <AsyncPanel loading={loading} title="Your course ideas" error={error} onRetry={onRetry} /> : matches.length ? matches.slice(0, 3).map((course) => <article className="studio-course" key={course.course_id}>
            <button className="studio-course-open" onClick={() => onOpenCourse(course.course_id)}><span>{course.provider} · {course.level || "Level not recorded"}</span><strong>{course.title}</strong><small>{course.rating_mean ? `★ ${course.rating_mean}/${course.rating_scale || 5} · ${Number(course.rating_count || 0).toLocaleString()} ratings` : "No learner rating recorded"}</small><ArrowUpRight size={17} aria-hidden="true" /></button>
            <button className="studio-save" aria-label={`${saved.has(course.course_id) ? "Unsave" : "Save"} ${course.title}`} aria-pressed={saved.has(course.course_id)} onClick={() => onSaveCourse(course.course_id)}><Bookmark size={17} fill={saved.has(course.course_id) ? "currentColor" : "none"} aria-hidden="true" /><span>{saved.has(course.course_id) ? "Saved" : "Save"}</span></button>
          </article>) : <p>No courses recorded for this interest yet. Other directions are still open.</p>}
          <span className="studio-smallprint">Highest recorded ratings shown first. Ratings are learner feedback, not an endorsement.</span>
        </div>
      </div>
    </section>
  );
}

export function VisitFeedback() {
 const choices=['Yes, a useful next step','Still finding my way','Too much to take in'];
 const [feedback,setFeedback,status]=usePersistentState('curricupath-visit-feedback',{response:'',reason:'',date:''});const [undo,setUndo]=useState(null);
 const response=choices.includes(feedback.response)?feedback.response:'';
 return <section className="visit-feedback" aria-labelledby="feedback-heading"><div><span className="eyebrow">A moment to reflect</span><h2 id="feedback-heading">Did you find a little clarity?</h2><p>Your response and optional reason stay on this device. Nothing is sent to a team.</p></div><div><div className="feedback-options" role="group" aria-label="How useful was this visit?">{choices.map(value=><button key={value} aria-pressed={response===value} onClick={()=>setFeedback({...feedback,response:value,date:new Date().toISOString()})}>{value}</button>)}</div>{response && <label className="workspace-field">What helped or got in the way? (optional)<textarea name="feedback-reason" autoComplete="off" maxLength={1000} rows={3} value={typeof feedback.reason==='string'?feedback.reason:''} onChange={e=>setFeedback({...feedback,reason:e.target.value})}/></label>}<p className="feedback-notice" role="status">{status==='error'?'Local saving failed; feedback may last only for this visit.':response?'Noted on this device. You can revise it. Nothing was sent.':''}</p>{response && <button className="text-button" onClick={()=>{setUndo(feedback);setFeedback({response:'',reason:'',date:''});}}>Clear my response</button>}{undo && <button className="text-button" onClick={()=>{setFeedback(undo);setUndo(null);}}>Undo feedback clear</button>}</div></section>;
}
