import React, { useState } from 'react';
import { previewCodes,applyPreview } from '../academicWorkspace.mjs';
export function HistoryImport({profile,modules,onApply}) {
  const [text,setText]=useState(''),[field,setField]=useState('completed'),[reviewing,setReviewing]=useState(false),[feedback,setFeedback]=useState('');
  const preview=previewCodes(text,modules,profile,field);
  return <details className="history-import"><summary>Paste module codes and review before applying</summary><p>Separate codes with spaces, commas or new lines. Recognised optional suffixes are resolved against this programme's catalogue.</p><label className="workspace-field">Declare these codes as<select value={field} onChange={e=>{setField(e.target.value);setReviewing(false);}}>{['completed','current','planned','repeating'].map(state=><option key={state} value={state}>{state}</option>)}</select></label><label className="workspace-field">Module codes<textarea name="history-import" autoComplete="off" spellCheck={false} rows={3} maxLength={2000} value={text} onChange={e=>{setText(e.target.value);setReviewing(false);}} placeholder="For example, ELEN3009A, APPM3021A…"/></label><button className="secondary-button" disabled={!text.trim() || !modules.length} onClick={()=>setReviewing(true)}>Preview module declarations</button>
    {reviewing && <section className="import-preview" aria-live="polite"><h3>Review this change.</h3><p><strong>{preview.valid.length} recognised:</strong> {preview.valid.join(', ') || 'none'}</p><p><strong>Unknown codes left out:</strong> {preview.unknown.join(', ') || 'none'}</p><p><strong>Duplicates left out:</strong> {preview.duplicates.join(', ') || 'none'}</p>{preview.moves.length>0 && <div className="workspace-warning">{preview.moves.map(move=><p key={move.code}>{move.code}: move from {move.from} to {move.to}</p>)}</div>}{preview.truncated && <p>Only the first 150 entries are included. Split a larger import into smaller groups.</p>}<p>Applying these declarations does not confirm that your entire history is complete.</p><button className="primary-button" disabled={!preview.valid.length} onClick={()=>{onApply(applyPreview(profile,preview,field));setFeedback(`${preview.valid.length} recognised codes applied as ${field}. Unknown entries were not added.`);setReviewing(false);setText('');}}>Apply reviewed declarations</button></section>}
    <p role="status">{feedback}</p>
  </details>;
}
